/**
 * The shipped 192×192 reference derivatives of the curated catalogue (E7).
 *
 * The files are generated by `scripts/generate-material-thumbnails.mjs` through
 * the inspection host. A row is used only while its key equals the key the
 * current catalogue entry and recipe versions produce, so a changed entry falls
 * back to its colour swatch rather than showing a stale picture. Looking one up
 * resolves a description only: it never loads a texture.
 */
import manifest from '$lib/content/material-thumbnails.json';
import type { MaterialId } from '$lib/types/materials';
import { inspectionThumbnailKey } from './inspection';
import { resolveInspectionSubject } from './inspection-subject';

export type CatalogueThumbnailRow = {
	readonly id: string;
	readonly key: string;
	readonly file: string;
	readonly width: number;
	readonly height: number;
	readonly geometry: 'sphere';
	readonly sha256: string;
};

const rows = new Map(
	(manifest.thumbnails as readonly CatalogueThumbnailRow[]).map((row) => [row.id, row])
);
const resolved = new Map<MaterialId, string | undefined>();

/** The shipped thumbnail of one catalogue entry, or undefined when none is current. */
export function catalogueThumbnailUri(id: MaterialId): string | undefined {
	if (resolved.has(id)) return resolved.get(id);
	const row = rows.get(id);
	let uri: string | undefined;
	if (row !== undefined) {
		const { recipeKey } = resolveInspectionSubject({ kind: 'catalogue', id }, row.geometry);
		if (
			recipeKey !== null &&
			inspectionThumbnailKey({ recipeKey, geometry: row.geometry, width: row.width, height: row.height }) === row.key
		) {
			uri = `/material-thumbnails/${row.file}`;
		}
	}
	resolved.set(id, uri);
	return uri;
}
